import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), sceneRoot=$('#scene');
const scene=new THREE.Scene();scene.background=new THREE.Color('#8bdfff');scene.fog=new THREE.Fog('#b9edfa',105,250);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,320);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;sceneRoot.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xe4f9ff,0x557c3f,2.1));const sun=new THREE.DirectionalLight(0xfff0cf,3.2);sun.position.set(-35,55,-25);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-70;sun.shadow.camera.right=70;sun.shadow.camera.top=70;sun.shadow.camera.bottom=-70;scene.add(sun);
const mat=(color,roughness=.8,extra={})=>new THREE.MeshStandardMaterial({color,roughness,...extra});
const grass=mat('#67b947'),darkGrass=mat('#438e43'),roadEdge=mat('#f3eee0'),red=mat('#e94f43'),white=mat('#fff8e9'),dark=mat('#253640'),gold=mat('#ffc947'),asphalt=makeAsphalt();
const ground=new THREE.Mesh(new THREE.PlaneGeometry(340,340),grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.3;ground.receiveShadow=true;scene.add(ground);
// A rounded-rectangle circuit: long horizontal start/finish straight, four broad, drivable bends.
const R=12, HALF_X=29, HALF_Z=20, STRAIGHT_X=HALF_X-R, STRAIGHT_Z=HALF_Z-R;
const lengths=[2*STRAIGHT_X,Math.PI*R/2,2*STRAIGHT_Z,Math.PI*R/2,2*STRAIGHT_X,Math.PI*R/2,2*STRAIGHT_Z,Math.PI*R/2];
const starts=[];let TRACK_LENGTH=0;for(const l of lengths){starts.push(TRACK_LENGTH);TRACK_LENGTH+=l}
function rawAt(s){s=((s%TRACK_LENGTH)+TRACK_LENGTH)%TRACK_LENGTH;
 if(s<lengths[0])return new THREE.Vector3(-STRAIGHT_X+s,0,-HALF_Z);
 s-=lengths[0];if(s<lengths[1]){const a=-Math.PI/2+s/R;return new THREE.Vector3(STRAIGHT_X+R*Math.cos(a),0,-STRAIGHT_Z+R*Math.sin(a))}
 s-=lengths[1];if(s<lengths[2])return new THREE.Vector3(HALF_X,0,-STRAIGHT_Z+s);
 s-=lengths[2];if(s<lengths[3]){const a=s/R;return new THREE.Vector3(STRAIGHT_X+R*Math.cos(a),0,STRAIGHT_Z+R*Math.sin(a))}
 s-=lengths[3];if(s<lengths[4])return new THREE.Vector3(STRAIGHT_X-s,0,HALF_Z);
 s-=lengths[4];if(s<lengths[5]){const a=Math.PI/2+s/R;return new THREE.Vector3(-STRAIGHT_X+R*Math.cos(a),0,STRAIGHT_Z+R*Math.sin(a))}
 s-=lengths[5];if(s<lengths[6])return new THREE.Vector3(-HALF_X,0,STRAIGHT_Z-s);
 s-=lengths[6];const a=Math.PI+s/R;return new THREE.Vector3(-STRAIGHT_X+R*Math.cos(a),0,-STRAIGHT_Z+R*Math.sin(a))}
function center(t){return rawAt(t/(Math.PI*2)*TRACK_LENGTH)}
function point(t,lane=0){const p=center(t),a=center(t+.002),b=center(t-.002),d=a.sub(b).normalize();p.x-=d.z*lane;p.z+=d.x*lane;return p}
function tangent(t){return center(t+.002).sub(center(t-.002)).normalize()}
function makeAsphalt(){const c=document.createElement('canvas');c.width=512;c.height=512;const x=c.getContext('2d');x.fillStyle='#414b51';x.fillRect(0,0,512,512);for(let i=0;i<18000;i++){const g=70+Math.random()*65;x.fillStyle=`rgba(${g},${g+4},${g+7},${Math.random()*.25})`;x.fillRect(Math.random()*512,Math.random()*512,1+Math.random()*2,1)}for(let i=0;i<12;i++){x.strokeStyle='rgba(20,27,30,.13)';x.lineWidth=7;x.beginPath();x.moveTo(i*48,0);x.lineTo(i*48+30,512);x.stroke()}const tex=new THREE.CanvasTexture(c);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.repeat.set(8,1);tex.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshStandardMaterial({map:tex,color:'#d7dee0',roughness:.92})}
function trackStrip(inner,outer,y,material,steps=480){const v=[],uv=[],idx=[];for(let i=0;i<=steps;i++){const t=i/steps*Math.PI*2,p=point(t,inner),q=point(t,outer);v.push(p.x,y,p.z,q.x,y,q.z);uv.push(i/steps*8,0,i/steps*8,1);if(i<steps){const n=i*2;idx.push(n,n+2,n+1,n+1,n+2,n+3)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();const mesh=new THREE.Mesh(g,material);mesh.receiveShadow=true;scene.add(mesh);return mesh}
trackStrip(-6.3,6.3,-.08,roadEdge);trackStrip(-5.65,5.65,-.035,asphalt);
trackStrip(-5.7,-5.5,-.012,mat('#fff4d8'));trackStrip(5.5,5.7,-.012,mat('#fff4d8'));
// Red-and-cream raised kerbs, with a bright edge and a painted inner racing guide.
